Корень и shared готовы — добавляю каркас `apps/server`.```json
{"version":1,"taskId":"a774d560-174b-4dd3-aa4b-e675234cf2f5","commandId":"scaffold-server-1","operation":"run","headSha":"d0db4c9c0b6931d24eaa55511e7f39a729109667","timeoutSeconds":60,"command":"set -euo pipefail
mkdir -p apps/server/src/{auth,chats,media,ws,store} apps/server/__tests__

cat > apps/server/package.json <<'EOF'
{
  "name": "@msngr/server",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "main": "./dist/index.js",
  "scripts": {
    "dev": "tsx watch src/index.ts",
    "build": "tsc -p tsconfig.json",
    "start": "node dist/index.js",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "lint": "eslint src --max-warnings=0",
    "test": "NODE_OPTIONS=--experimental-vm-modules jest"
  },
  "dependencies": {
    "@msngr/shared": "0.1.0",
    "fastify": "^5.2.1",
    "ws": "^8.18.0"
  },
  "devDependencies": {
    "@types/jest": "^29.5.14",
    "@types/node": "^22.10.5",
    "@types/ws": "^8.5.13",
    "jest": "^29.7.0",
    "ts-jest": "^29.2.5",
    "tsx": "^4.19.2",
    "typescript": "^5.7.3"
  }
}
EOF

cat > apps/server/tsconfig.json <<'EOF'
{
  "extends": "../../tsconfig.base.json",
  "compilerOptions": {
    "outDir": "dist",
    "rootDir": "src",
    "types": ["node"]
  },
  "include": ["src/**/*.ts"],
  "references": [{ "path": "../../packages/shared" }]
}
EOF

cat > apps/server/jest.config.cjs <<'EOF'
/** @type {import('jest').Config} */
module.exports = {
  preset: 'ts-jest/presets/default-esm',
  testEnvironment: 'node',
  roots: ['<rootDir>/src', '<rootDir>/__tests__'],
  extensionsToTreatAsEsm: ['.ts'],
  moduleNameMapper: {
    '^(\\.{1,2}/.*)\\.js$': '$1',
    '^@msngr/shared$': '<rootDir>/../../packages/shared/src/index.ts',
  },
};
EOF

cat > apps/server/src/config.ts <<'EOF'
export type ServerConfig = {
  host: string;
  port: number;
};

export function loadConfig(env: NodeJS.ProcessEnv = process.env): ServerConfig {
  const port = Number(env.PORT ?? 3000);
  if (!Number.isFinite(port) || port <= 0) {
    throw new Error(`Invalid PORT: ${env.PORT ?? ''}`);
  }
  return {
    host: env.HOST ?? '0.0.0.0',
    port,
  };
}
EOF

cat > apps/server/src/app.ts <<'EOF'
import Fastify, { type FastifyInstance } from 'fastify';
import { API_PREFIX } from '@msngr/shared';

export async function buildApp(): Promise<FastifyInstance> {
  const app = Fastify({ logger: true });

  app.get('/health', async () => ({
    ok: true,
    service: 'msngr-server',
  }));

  app.get(API_PREFIX, async () => ({
    name: 'msngr',
    version: 1,
    prefix: API_PREFIX,
  }));

  return app;
}
EOF

cat > apps/server/src/index.ts <<'EOF'
import { buildApp } from './app.js';
import { loadConfig } from './config.js';

async function main(): Promise<void> {
  const config = loadConfig();
  const app = await buildApp();
  await app.listen({ host: config.host, port: config.port });
}

main().catch((err: unknown) => {
  console.error(err);
  process.exit(1);
});
EOF

cat > apps/server/__tests__/app.test.ts <<'EOF'
import { buildApp } from '../src/app.js';

describe('server app', () => {
  it('responds on /health', async () => {
    const app = await buildApp();
    const res = await app.inject({ method: 'GET', url: '/health' });
    expect(res.statusCode).toBe(200);
    expect(res.json()).toMatchObject({ ok: true, service: 'msngr-server' });
    await app.close();
  });
});
EOF

cat > apps/server/__tests__/config.test.ts <<'EOF'
import { loadConfig } from '../src/config.js';

describe('loadConfig', () => {
  it('uses defaults', () => {
    expect(loadConfig({})).toEqual({ host: '0.0.0.0', port: 3000 });
  });

  it('reads PORT and HOST', () => {
    expect(loadConfig({ PORT: '4100', HOST: '127.0.0.1' })).toEqual({
      host: '127.0.0.1',
      port: 4100,
    });
  });
});
EOF

touch apps/server/src/auth/.gitkeep apps/server/src/chats/.gitkeep \
  apps/server/src/media/.gitkeep apps/server/src/ws/.gitkeep \
  apps/server/src/store/.gitkeep

echo OK_SERVER
ls apps/server/src apps/server/__tests__
"}
```

